1	// Meeting-room booking server: JSON API, static page, one JSON data file.
2	// Node.js built-ins only.
3	import { createServer } from 'node:http';
4	import { readFile, writeFile } from 'node:fs/promises';
5	import { dirname, join, resolve } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	const HOST = '127.0.0.1';
10	const DEFAULT_PORT = 3000;
11	const DEFAULT_DATA_FILE = 'bookings.json';
12	const MAX_BODY_BYTES = 10000;
13	const JSON_TYPE = 'application/json; charset=utf-8';
14	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
15	const BOOKINGS_PREFIX = '/api/bookings/';
16	const PUBLIC_DIR = join(dirname(fileURLToPath(import.meta.url)), 'public');
17	const STATIC_FILES = Object.freeze({
18	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
19	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
20	});
21	
22	const MSG = Object.freeze({
23	  internal: 'internal error',
24	  notFound: 'not found',
25	  method: 'method not allowed',
26	  bookingNotFound: 'booking not found',
27	  contentType: 'content type must be application/json',
28	  tooLarge: 'body too large',
29	  notObject: 'body must be a JSON object',
30	  room: 'room must be one of Aurora, Borealis, Cosmos',
31	  title: 'title must be 1 to 80 characters',
32	  date: 'date must be a valid YYYY-MM-DD date',
33	  start: 'start must be HH:MM',
34	  end: 'end must be HH:MM',
35	  order: 'end must be after start',
36	});
37	
38	// ---------- validation helpers ----------
39	
40	const isPlainObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
41	
42	function isValidDate(value) {
43	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
44	  const year = Number(value.slice(0, 4));
45	  const month = Number(value.slice(5, 7));
46	  const day = Number(value.slice(8, 10));
47	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
48	  const daysInMonth = [31, year % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
49	  return day <= daysInMonth[month - 1];
50	}
51	
52	function isValidTime(value) {
53	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
54	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
55	}
56	
57	/** A title is valid when, trimmed, it holds 1 to 80 UTF-16 code units. */
58	function isValidTitle(value) {
59	  if (typeof value !== 'string') return false;
60	  const length = value.trim().length;
61	  return length >= 1 && length <= 80;
62	}
63	
64	const overlaps = (a, b) =>
65	  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
66	
67	const compareText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
68	
69	/** Returns an error message for the first failing field rule (4-9), or null. */
70	function fieldError(body) {
71	  if (!ROOMS.includes(body.room)) return MSG.room;
72	  if (!isValidTitle(body.title)) return MSG.title;
73	  if (!isValidDate(body.date)) return MSG.date;
74	  if (!isValidTime(body.start)) return MSG.start;
75	  if (!isValidTime(body.end)) return MSG.end;
76	  if (body.end <= body.start) return MSG.order;
77	  return null;
78	}
79	
80	// ---------- data file ----------
81	
82	function isStoredBooking(b, nextId) {
83	  if (!isPlainObject(b)) return false;
84	  const keys = Object.keys(b);
85	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => Object.hasOwn(b, k))) {
86	    return false;
87	  }
88	  if (!Number.isSafeInteger(b.id) || b.id < 1 || b.id >= nextId) return false;
89	  if (!ROOMS.includes(b.room) || !isValidDate(b.date)) return false;
90	  if (!isValidTitle(b.title) || b.title !== b.title.trim()) return false;
91	  return isValidTime(b.start) && isValidTime(b.end) && b.start < b.end;
92	}
93	
94	/** Strict check that `data` is exactly what this server writes. */
95	function isValidStore(data) {
96	  if (!isPlainObject(data)) return false;
97	  const keys = Object.keys(data);
98	  if (keys.length !== 2 || !Object.hasOwn(data, 'nextId') || !Object.hasOwn(data, 'bookings')) {
99	    return false;
100	  }
101	  const { nextId, bookings } = data;
102	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
103	  if (!bookings.every((b) => isStoredBooking(b, nextId))) return false;
104	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return false;
105	  return bookings.every((b, i) => bookings.slice(i + 1).every((o) => !overlaps(b, o)));
106	}
107	
108	const emptyStore = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
109	
110	/** Resolves to the loaded store, or null when the file exists but is unusable. */
111	async function loadStore(path) {
112	  let text;
113	  try {
114	    text = await readFile(path, 'utf8');
115	  } catch (err) {
116	    if (err && err.code === 'ENOENT') return emptyStore();
117	    return null;
118	  }
119	  let data;
120	  try {
121	    data = JSON.parse(text);
122	  } catch {
123	    return null;
124	  }
125	  if (!isValidStore(data)) return null;
126	  return Object.freeze({
127	    nextId: data.nextId,
128	    bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))),
129	  });
130	}
131	
132	const saveStore = (path, store) => writeFile(path, JSON.stringify(store));
133	
134	// ---------- HTTP helpers ----------
135	
136	function sendJson(res, status, payload) {
137	  const body = JSON.stringify(payload);
138	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
139	  res.end(body);
140	}
141	
142	const sendError = (res, status, message) => sendJson(res, status, { error: message });
143	
144	function sendNoContent(res) {
145	  res.writeHead(204);
146	  res.end();
147	}
148	
149	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes, counts all of them. */
150	function readBody(req) {
151	  return new Promise((resolveBody, rejectBody) => {
152	    const chunks = [];
153	    let size = 0;
154	    let kept = 0;
155	    req.on('data', (chunk) => {
156	      size += chunk.length;
157	      if (kept <= MAX_BODY_BYTES) {
158	        chunks.push(chunk);
159	        kept += chunk.length;
160	      }
161	    });
162	    req.on('end', () => resolveBody({ size, buffer: Buffer.concat(chunks) }));
163	    req.on('error', rejectBody);
164	    req.on('close', () => {
165	      if (!req.complete) rejectBody(new Error('request closed before its body was read'));
166	    });
167	  });
168	}
169	
170	function mediaType(header) {
171	  if (typeof header !== 'string') return null;
172	  return header
173	    .split(';')[0]
174	    .replace(/^[ \t]+|[ \t]+$/g, '')
175	    .replace(/[A-Z]/g, (c) => c.toLowerCase());
176	}
177	
178	function parseObject(buffer) {
179	  try {
180	    const value = JSON.parse(buffer.toString('utf8'));
181	    return isPlainObject(value) ? value : null;
182	  } catch {
183	    return null;
184	  }
185	}
186	
187	const compareByStart = (a, b) => compareText(a.start, b.start);
188	
189	function compareBookings(a, b) {
190	  return (
191	    compareText(a.date, b.date) ||
192	    compareByStart(a, b) ||
193	    ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room) ||
194	    a.id - b.id
195	  );
196	}
197	
198	// ---------- application ----------
199	
200	/**
201	 * Holds the in-memory store (the source of truth after startup) and runs
202	 * mutations one at a time. `commit` saves first and only then replaces the
203	 * store, so a failed save changes nothing, the next id included.
204	 */
205	function createRepository(dataPath, initialStore) {
206	  let store = initialStore;
207	  let queue = Promise.resolve();
208	  return Object.freeze({
209	    current: () => store,
210	    // The returned promise carries the task's own result or error to the
211	    // caller; the chain only needs to settle so the next task can run.
212	    serialize(task) {
213	      const run = queue.then(task);
214	      queue = run.then(
215	        () => undefined,
216	        () => undefined,
217	      );
218	      return run;
219	    },
220	    async commit(next) {
221	      await saveStore(dataPath, next);
222	      store = next;
223	    },
224	  });
225	}
226	
227	function listBookings(repo, res, query) {
228	  const params = new URLSearchParams(query);
229	  let bookings = repo.current().bookings;
230	  if (params.has('date')) {
231	    const date = params.get('date');
232	    if (!isValidDate(date)) return sendError(res, 400, MSG.date);
233	    bookings = bookings.filter((b) => b.date === date);
234	  }
235	  return sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
236	}
237	
238	/** Applies booking rules 1-9; returns the booking fields, or null after replying. */
239	function readBookingInput(req, res, body) {
240	  if (mediaType(req.headers['content-type']) !== 'application/json') {
241	    sendError(res, 415, MSG.contentType);
242	    return null;
243	  }
244	  if (body.size > MAX_BODY_BYTES) {
245	    sendError(res, 413, MSG.tooLarge);
246	    return null;
247	  }
248	  const input = parseObject(body.buffer);
249	  const invalid = input === null ? MSG.notObject : fieldError(input);
250	  if (invalid !== null) {
251	    sendError(res, 400, invalid);
252	    return null;
253	  }
254	  const { room, title, date, start, end } = input;
255	  return Object.freeze({ room, title: title.trim(), date, start, end });
256	}
257	
258	function createBooking(repo, req, res, body) {
259	  const fields = readBookingInput(req, res, body);
260	  if (fields === null) return undefined;
261	  return repo.serialize(async () => {
262	    const store = repo.current();
263	    const [clash] = store.bookings.filter((b) => overlaps(b, fields)).sort(compareByStart);
264	    if (clash) {
265	      return sendError(res, 409, `room is already booked from ${clash.start} to ${clash.end}`);
266	    }
267	    const booking = Object.freeze({ id: store.nextId, ...fields });
268	    await repo.commit(
269	      Object.freeze({
270	        nextId: store.nextId + 1,
271	        bookings: Object.freeze([...store.bookings, booking]),
272	      }),
273	    );
274	    return sendJson(res, 201, booking);
275	  });
276	}
277	
278	function deleteBooking(repo, res, idText) {
279	  return repo.serialize(async () => {
280	    const store = repo.current();
281	    const found =
282	      /^[1-9][0-9]*$/.test(idText) && store.bookings.some((b) => String(b.id) === idText);
283	    if (!found) return sendError(res, 404, MSG.bookingNotFound);
284	    await repo.commit(
285	      Object.freeze({
286	        nextId: store.nextId,
287	        bookings: Object.freeze(store.bookings.filter((b) => String(b.id) !== idText)),
288	      }),
289	    );
290	    return sendNoContent(res);
291	  });
292	}
293	
294	async function serveStatic(res, entry) {
295	  const content = await readFile(join(PUBLIC_DIR, entry.file));
296	  res.writeHead(200, { 'Content-Type': entry.type, 'Content-Length': content.length });
297	  res.end(content);
298	}
299	
300	/** Splits the raw request target at the first `?`; nothing is decoded. */
301	function splitTarget(target) {
302	  const qIndex = target.indexOf('?');
303	  return qIndex === -1
304	    ? { path: target, query: '' }
305	    : { path: target.slice(0, qIndex), query: target.slice(qIndex + 1) };
306	}
307	
308	function route(repo, req, res, body) {
309	  const { path, query } = splitTarget(req.url ?? '');
310	  const { method } = req;
311	  const notAllowed = () => sendError(res, 405, MSG.method);
312	
313	  if (path === '/api/rooms') {
314	    return method === 'GET' ? sendJson(res, 200, { rooms: [...ROOMS] }) : notAllowed();
315	  }
316	  if (path === '/api/bookings') {
317	    if (method === 'GET') return listBookings(repo, res, query);
318	    if (method === 'POST') return createBooking(repo, req, res, body);
319	    return notAllowed();
320	  }
321	  if (path.startsWith(BOOKINGS_PREFIX)) {
322	    const idText = path.slice(BOOKINGS_PREFIX.length);
323	    if (idText === '' || idText.includes('/')) return sendError(res, 404, MSG.notFound);
324	    return method === 'DELETE' ? deleteBooking(repo, res, idText) : notAllowed();
325	  }
326	  if (Object.hasOwn(STATIC_FILES, path)) {
327	    return method === 'GET' ? serveStatic(res, STATIC_FILES[path]) : notAllowed();
328	  }
329	  return sendError(res, 404, MSG.notFound);
330	}
331	
332	function replyInternalError(res) {
333	  if (res.headersSent) {
334	    res.destroy();
335	    return;
336	  }
337	  sendError(res, 500, MSG.internal);
338	}
339	
340	function createHandler(repo) {
341	  return async function handle(req, res) {
342	    try {
343	      const body = await readBody(req);
344	      await route(repo, req, res, body);
345	    } catch {
346	      // Any unexpected failure (save error, unreadable page, broken request)
347	      // becomes a generic 500; details are never sent to the client.
348	      replyInternalError(res);
349	    }
350	  };
351	}
352	
353	// ---------- startup ----------
354	
355	function fail(line) {
356	  process.stderr.write(`${line}\n`, () => process.exit(1));
357	}
358	
359	function parsePort(raw) {
360	  if (raw === undefined || raw === '') return DEFAULT_PORT;
361	  if (!/^[0-9]+$/.test(raw)) return null;
362	  const port = Number(raw);
363	  return port <= 65535 ? port : null;
364	}
365	
366	async function main() {
367	  const port = parsePort(process.env.PORT);
368	  // JSON.stringify keeps a value holding line breaks on one stderr line.
369	  if (port === null) return fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
370	
371	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
372	  const dataPath = resolve(process.cwd(), dataName);
373	  const store = await loadStore(dataPath);
374	  if (store === null) return fail(`cannot read data file ${dataName}`);
375	
376	  const handle = createHandler(createRepository(dataPath, store));
377	  const server = createServer((req, res) => {
378	    handle(req, res).catch(() => res.destroy());
379	  });
380	  const onListenError = (err) => fail(`cannot listen on ${HOST}:${port}: ${err.code ?? 'error'}`);
381	  server.once('error', onListenError);
382	  server.listen(port, HOST, () => {
383	    server.off('error', onListenError);
384	    server.on('error', reportServerError);
385	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
386	  });
387	  return undefined;
388	}
389	
390	/** A server error after startup is reported on stderr; the server keeps running. */
391	function reportServerError(err) {
392	  process.stderr.write(`server error: ${err?.code ?? 'unknown'}\n`);
393	}
394	
395	main().catch(() => fail('server failed to start'));
